def semver_sort(versions):
    def parse_key(v):
        main = v.split('+', 1)[0]
        if '-' in main:
            core, prerelease = main.split('-', 1)
        else:
            core, prerelease = main, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if prerelease is None:
            has_prerelease_flag = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_prerelease_flag = 0  # has prerelease sorts before
            idents = prerelease.split('.')
            pre_key = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in idents
            )

        return (major, minor, patch, has_prerelease_flag, pre_key)

    return sorted(versions, key=parse_key)

